def _need(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")


def _div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    return int(a / b)


_BINARY = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': _div,
}


def _is_number(token):
    return token.lstrip('-').isdigit() and token not in ('-',)


def evaluate(input_data):
    stack = []
    words = {}

    def run(token):
        if _is_number(token):
            stack.append(int(token))
        elif token in _BINARY:
            _need(stack, 2)
            b = stack.pop()
            a = stack.pop()
            stack.append(_BINARY[token](a, b))
        elif token == 'dup':
            _need(stack, 1)
            stack.append(stack[-1])
        elif token == 'drop':
            _need(stack, 1)
            stack.pop()
        elif token == 'swap':
            _need(stack, 2)
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif token == 'over':
            _need(stack, 2)
            stack.append(stack[-2])
        else:
            raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.lower().split()
        i = 0
        while i < len(tokens):
            token = tokens[i]
